-- Shoto Point CMS v2 additional schema. server.js creates these automatically.
CREATE TABLE IF NOT EXISTS cms_content_meta (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, content_id BIGINT UNSIGNED NOT NULL UNIQUE,
 menu_id BIGINT UNSIGNED NULL, placement VARCHAR(60) DEFAULT 'content', align_mode VARCHAR(40) DEFAULT 'center',
 font_family VARCHAR(120) DEFAULT 'Arial', font_size VARCHAR(30) DEFAULT '16px', font_weight VARCHAR(30) DEFAULT '400',
 font_style VARCHAR(30) DEFAULT 'normal', text_decoration VARCHAR(30) DEFAULT 'none', layout_mode VARCHAR(60) DEFAULT 'full-width',
 blocks_json JSON NULL, seo_json JSON NULL, social_json JSON NULL, updated_by BIGINT NULL,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_site_settings(setting_key VARCHAR(120) PRIMARY KEY,setting_value LONGTEXT NULL,updated_by BIGINT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_integrations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(80) NOT NULL UNIQUE,enabled TINYINT(1) DEFAULT 0,public_config_json JSON NULL,secret_config_json JSON NULL,updated_by BIGINT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_security_settings(id TINYINT PRIMARY KEY,two_factor_enabled TINYINT(1) DEFAULT 0,two_factor_secret VARCHAR(64) DEFAULT NULL,session_minutes INT DEFAULT 480,max_login_attempts INT DEFAULT 5,lockout_minutes INT DEFAULT 15,require_approval_for_members TINYINT(1) DEFAULT 1,require_approval_for_content TINYINT(1) DEFAULT 1,require_approval_for_withdrawals TINYINT(1) DEFAULT 1,updated_by BIGINT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT NULL,identifier VARCHAR(255) NOT NULL,success TINYINT(1) DEFAULT 0,ip_address VARCHAR(100) DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_message_templates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,template_key VARCHAR(100) NOT NULL UNIQUE,channel VARCHAR(30) DEFAULT 'email',subject VARCHAR(255) DEFAULT '',body LONGTEXT NULL,enabled TINYINT(1) DEFAULT 1,updated_by BIGINT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_meeting_links(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meeting_id BIGINT NOT NULL,provider VARCHAR(50) NOT NULL,join_url VARCHAR(1000) NOT NULL,host_url VARCHAR(1000) NOT NULL,access_code VARCHAR(100) DEFAULT '',created_by BIGINT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_wallet_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type VARCHAR(30) NOT NULL,amount DECIMAL(14,2) NOT NULL,reference VARCHAR(120) DEFAULT NULL,status VARCHAR(40) DEFAULT 'pending',provider VARCHAR(40) DEFAULT 'paystack',details_json JSON NULL,created_by BIGINT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
